def format_mcq(item_id, item_data):
    q, options, exp, kp = item_data
    # Construct 4 rationales: first is Correct., rest are Incorrect.
    r = [
        f"Correct. {exp.split('.')[0]}."
    ]
    for opt in options[1:]:
        r.append(f"Incorrect. {opt} does not explain the primary biochemical mechanism described.")
    
    return {
        "id": f"bk-bio-{item_id:03d}",
        "q": q,
        "o": options,
        "a": 0,
        "exp": exp,
        "r": r,
        "kp": kp,
        "img": [],
        "d": 1 if item_id % 2 == 1 else 2,
        "cog": "recall" if item_id % 2 == 1 else "application"
    }

def main():
    part1_data = {}
    part2_data = {}
    part3_data = {}
    
    cur_id = 211
    for mod_key, part_num, questions in DATA:
        assert len(questions) == 10, f"{mod_key} has {len(questions)} questions"
        mod_items = []
        for q_data in questions:
            mod_items.append(format_mcq(cur_id, q_data))
            cur_id += 1
        
        if part_num == 1:
            part1_data[mod_key] = mod_items
        elif part_num == 2:
            part2_data[mod_key] = mod_items
        elif part_num == 3:
            part3_data[mod_key] = mod_items
        else:
            raise ValueError(f"Invalid part {part_num}")

    print(f"Generated {cur_id - 211} total questions (bk-bio-211 to bk-bio-{cur_id - 1})")

    # Write part 1
    with open("tools/wave3b-mcqs-part1.mjs", "w") as f:
        f.write("/**\n * Wave 3B Original MCQs: Part 1 (Modules 1-8, bk-bio-211 to bk-bio-290)\n */\n\n")
        f.write("export const wave3bMcqsPart1 = " + json.dumps(part1_data, indent=2) + ";\n")
    print("Wrote tools/wave3b-mcqs-part1.mjs (80 MCQs)")

    # Write part 2
    with open("tools/wave3b-mcqs-part2.mjs", "w") as f:
        f.write("/**\n * Wave 3B Original MCQs: Part 2 (Modules 9-16, bk-bio-291 to bk-bio-370)\n */\n\n")
        f.write("export const wave3bMcqsPart2 = " + json.dumps(part2_data, indent=2) + ";\n")
    print("Wrote tools/wave3b-mcqs-part2.mjs (80 MCQs)")

    # Write part 3
    with open("tools/wave3b-mcqs-part3.mjs", "w") as f:
        f.write("/**\n * Wave 3B Original MCQs: Part 3 (Modules 17-23, bk-bio-371 to bk-bio-440)\n */\n\n")
        f.write("export const wave3bMcqsPart3 = " + json.dumps(part3_data, indent=2) + ";\n")
    print("Wrote tools/wave3b-mcqs-part3.mjs (70 MCQs)")

    # Write aggregator tools/wave3b-mcqs.mjs
    with open("tools/wave3b-mcqs.mjs", "w") as f:
        f.write("""/**
 * Aggregator for Wave 3B MCQs (230 questions across 23 modules)
 */
import { wave3bMcqsPart1 as part1 } from "./wave3b-mcqs-part1.mjs";
import { wave3bMcqsPart2 as part2 } from "./wave3b-mcqs-part2.mjs";
import { wave3bMcqsPart3 as part3 } from "./wave3b-mcqs-part3.mjs";

export const wave3bMcqs = {
  ...part1,
  ...part2,
  ...part3
};
""")
    print("Wrote tools/wave3b-mcqs.mjs (230 MCQs total)")

if __name__ == "__main__":
    main()
